    Count : INT := 0;
    PrevPulse : BOOL := FALSE;
    TmrReset : TON;
END_VAR

// Update edge detection for Pulse
PrevPulse := Pulse AND NOT PrevPulse;

// Increment Count on rising edge of Pulse if less than 2
IF Pulse AND NOT PrevPulse THEN
    IF Count < 2 THEN
        Count := Count + 1;
    END_IF;
