    Count := 0;
    Spindle := FALSE;
    TmrReset(IN := TRUE, PT := T#0s);
END_IF;

// Ensure Count does not exceed 2
IF Count > 2 THEN
    Count := 2;
END_IF;

END_PROGRAM

