ELSIF PumpTimer.Q THEN
    Pump := TRUE;
    PumpEnabled := TRUE;
ELSIF NOT StartCmd AND PumpEnabled THEN
    Pump := FALSE;
    PumpEnabled := FALSE;
END_IF;

END_PROGRAM

