PROGRAM p_cnt_3_spindle
VAR_INPUT
    Pulse : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Spindle : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevPulse : BOOL := FALSE;
END_VAR

Spindle := FALSE;

IF Reset THEN
    Count := 0;
    PrevPulse := FALSE;
ELSIF Pulse AND NOT PrevPulse THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
END_IF;

PrevPulse := Pulse;

IF Count = 3 THEN
    Spindle := TRUE;
END_IF;

END_PROGRAM

PROGRAM p_ovr_motor
VAR_INPUT
    Demand : BOOL;
    Enable : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    MotorOnTimer : TON;
END_VAR

Motor := FALSE;

IF Fault THEN
    Motor := FALSE;
    MotorOnTimer(IN := FALSE);
ELSIF Enable AND Demand THEN
    Motor := TRUE;
    MotorOnTimer(IN := TRUE, PT := T#0s);
ELSIF NOT Enable THEN
    Motor := FALSE;
    MotorOnTimer(IN := FALSE);
END_IF;

IF MotorOnTimer.Q THEN
    Motor := TRUE;
END_IF;
END_PROGRAM

PROGRAM p_mguard_3_drive
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    G1 : BOOL;
    G2 : BOOL;
    G3 : BOOL;
END_VAR

VAR_OUTPUT
    Drive : BOOL;
END_VAR

VAR
    DriveTimer : TON;
END_VAR

IF StopPB THEN
    Drive := FALSE;
    DriveTimer(IN := FALSE);
ELSIF StartPB AND G1 AND G2 AND G3 THEN
    DriveTimer(IN := TRUE, PT := T#1s);
    Drive := DriveTimer.Q;
ELSE
    Drive := FALSE;
    DriveTimer(IN := FALSE);
END_IF;

END_PROGRAM

PROGRAM p_cnt_5_drive
VAR_INPUT
    Pulse : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Drive : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevPulse : BOOL := FALSE;
END_VAR

// Update PrevPulse to detect rising edge of Pulse
PrevPulse := Pulse;

// Check for rising edge
IF Pulse AND NOT PrevPulse THEN
    // Increment Count if not already at max
    IF Count < 5 THEN
        Count := Count + 1;
    END_IF;
END_IF;

// Set Drive to TRUE when Count reaches 5
Drive := (Count = 5);

// Reset Count if Reset is TRUE
IF Reset THEN
    Count := 0;
    Drive := FALSE;
END_IF;
END_PROGRAM

